#!/usr/bin/env python3
"""Build the manufacturing analytical-case JSONL from explicit researched case declarations."""

from __future__ import annotations

import json
from pathlib import Path


HERE = Path(__file__).resolve().parent
INDUSTRY = "ind.manufacturing"
CASES: list[dict] = []


def add(
    suffix: str,
    name: str,
    subs: list[str],
    modes: list[str],
    question: str,
    action: str,
    unit: str,
    grain: str,
    systems: list[str],
    shapes: list[str],
    methods: list[str],
    operations: list[str],
    inputs: list[str],
    outputs: list[str],
    evidence: list[str],
    *,
    actors: list[str] | None = None,
    time: list[str] | None = None,
    assumptions: list[str] | None = None,
    invariants: list[str] | None = None,
    failures: list[str] | None = None,
    limitations: list[str] | None = None,
) -> None:
    CASES.append(
        {
            "record_id": f"mfg.case.{suffix}",
            "record_kind": "analytical_case",
            "edition": 1,
            "status": "sourced_candidate",
            "industry_id": INDUSTRY,
            "subindustry_ids": subs,
            "name": name,
            "analytical_modes": modes,
            "sovereign_question": question,
            "decision_or_action": action,
            "actors": actors or ["operations leader", "process or industrial engineer"],
            "unit_of_analysis": unit,
            "population": f"All {unit}s inside the declared site, product, process, and study window; exclusions are explicit.",
            "grain": grain,
            "time_model": time or ["event time", "valid time", "record time", "decision as-of time"],
            "source_system_refs": systems,
            "data_shape_refs": shapes,
            "method_refs": methods,
            "operation_refs": operations,
            "inputs": inputs,
            "outputs": outputs,
            "assumptions": assumptions
            or [
                "Identity, unit, clock, product mix, operating regime, and change effectivity are reconciled before analysis.",
                "The observation and sampling process is known well enough for the stated inference.",
            ],
            "invariants": invariants
            or [
                "Raw observations, derived features, hypotheses, recommendations, decisions, and executed actions remain distinct.",
                "As-designed, as-planned, as-executed, as-inspected, and as-maintained states are never silently conflated.",
                "Safety, quality, release, and command authority remain with accountable domain roles.",
            ],
            "failure_modes": failures
            or [
                "Selection, censoring, survivorship, regime, or measurement bias creates a false explanation.",
                "Late, duplicate, missing, compressed, or mis-keyed records corrupt sequence or scope.",
                "Correlation, ranking, or model importance is misrepresented as root cause.",
            ],
            "evidence_refs": evidence,
            "llm_dependency": "none",
            "limitations": limitations
            or [
                "The case does not authorize autonomous process, safety, release, maintenance, or personnel action.",
                "Transportability to another line, product, site, or regime requires revalidation.",
            ],
        }
    )


